const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3 }> = ({ tool, points, cursorPos }) => {
    const { formatValue } = useApp();
    const currentPoint = cursorPos;
    if (points.length === 0) return null;
    const startPoint = points[0];

    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) {
        const linePoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        linePoints.push(currentPoint);
        return <SimpleLine points={linePoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_RECT) {
        const p1 = startVec;
        const p2 = currentPoint;

        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);

        const rectPoints = [
            new THREE.Vector3(minX, 0, minZ),
            new THREE.Vector3(maxX, 0, minZ),
            new THREE.Vector3(maxX, 0, maxZ),
            new THREE.Vector3(minX, 0, maxZ),
            new THREE.Vector3(minX, 0, minZ),
        ];

        return <SimpleLine points={rectPoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
        return (
            <>
                <SimpleLine points={circlePoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
         return (
            <>
                <SimpleLine points={arcPoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    if (tool === ToolType.MEASURE) {
        if (points.length === 1) {
            // First click done, dragging to second point
            return (
                <>
                    <SimpleLine points={[startVec, currentPoint]} color="blue" dashed />
                    <mesh position={startVec}>
                        <sphereGeometry args={[0.05]} />
                        <meshBasicMaterial color="blue" />
                    </mesh>
                    <mesh position={currentPoint}>
                        <sphereGeometry args={[0.05]} />
                        <meshBasicMaterial color="blue" />
                    </mesh>
                </>
            );
        } else if (points.length === 2) {
            // Second click done, placing the dimension offset
            const p2 = new THREE.Vector3(points[1].x, points[1].y, points[1].z);

            // Calculate dimension geometry preview
            const v12 = new THREE.Vector3().subVectors(p2, startVec);
            const v13 = new THREE.Vector3().subVectors(currentPoint, startVec);
            const projection = v13.dot(v12) / v12.lengthSq();
            const projectedPoint = startVec.clone().add(v12.multiplyScalar(projection));
            const offsetVector = new THREE.Vector3().subVectors(currentPoint, projectedPoint);

            const dimStart = startVec.clone().add(offsetVector);
            const dimEnd = p2.clone().add(offsetVector);
            const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);

            return (
                 <group>
                    <SimpleLine points={[dimStart, dimEnd]} color="blue" />
                    <SimpleLine points={[startVec, dimStart]} color="gray" dashed />
                    <SimpleLine points={[p2, dimEnd]} color="gray" dashed />
                     <Text
                        position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}
                        fontSize={0.2}
                        color="blue"
                        anchorX="center"
                        anchorY="bottom"
                        outlineWidth={0.02}
                        outlineColor="#fff"
                    >
                        {formatValue(startVec.distanceTo(p2))}
                    </Text>
                 </group>
            );
        }
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput }) => {
    const { camera, scene } = useThree();
    const { setMeasurement, formatValue, layers } = useApp();

    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; // Last point
            const current = pos;

            // Calculate 3D distance
            const dist = Math.sqrt(
                (current.x - start.x)**2 + 
                (current.y - start.y)**2 + 
                (current.z - start.z)**2
            );

            if (tool === ToolType.DRAW_LINE) {
                text = `長度: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_RECT) {
                if (input) {
                    text = `寬度, 深度: ${input}`;
                } else {
                    const w = Math.abs(current.x - start.x);
                    const d = Math.abs(current.z - start.z);
                    text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`;
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_ARC) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.MEASURE) {
                 text = `距離: ${input ? input : formatValue(dist)}`;
            }
        } else {
             // Basic coordinate display when hovering
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC, ToolType.MEASURE].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
             }
        }

        if (input !== undefined) {
             text += '|'; // Add cursor block
        }
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement]);

    useEffect(() => {
        if (typedInput) {
            updateMeasurement(cursorPos, typedInput);
        }
    }, [typedInput, cursorPos, updateMeasurement]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const intersectPoint = e.point; 

        const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);

        // Filter out invisible layers
        const visibleIntersections = shapeIntersections.filter(i => {
            const obj = i.object;
            const shapeId = obj.userData?.id || obj.parent?.userData?.id;
            const shape = shapes.find(s => s.id === shapeId);
            if (!shape) return false;
            const layer = layers.find(l => l.id === shape.layerId);
            return layer ? layer.visible : true;
        });

        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;

        // Filter shapes for snapping to exclude hidden layers
        const visibleShapes = shapes.filter(s => {
             const layer = layers.find(l => l.id === s.layerId);
             return layer ? layer.visible : true;
        });

        const snap = getGeometrySnap(intersectPoint, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);

        setCursorPos(snap.position);
        setSnapInfo(snap);

        if (!typedInput) {
             updateMeasurement(snap.position);
        }

    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                visible={false} 
                onPointerMove={onPointerMove}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>

             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                </>
             )}

             {drawPoints.length > 0 && (
                <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} />
             )}
        </group>
    );
};

// ... Managers ...
const usePushPullManager = () => {
    const { tool, updateShape, shapes, setMeasurement, formatValue, layers } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined
    });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = e.intersections.find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;

        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id;
        else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape) return null;

        // Visibility check
        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        if (worldNormal.y > 0.9) return { mode: 'top', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, 1, 0) };
        if (worldNormal.y < -0.9) return { mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, -1, 0) }; 

        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);
            let closestIndex = -1;
            let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];
                const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z));
                if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; }
            }
            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal };
            }
        }
        return null;
    }, [shapes, layers]);

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
            if (ppState.mode === 'top') {
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);
                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                    setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                    setMeasurement(`高度: ${formatValue(newHeight)}`);
                }
            } else if (ppState.mode === 'side') {
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);
                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);

                    setMeasurement(`偏移: ${formatValue(projection)}`);

                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);
                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];
                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];
                    p1.x += dLocalX; p1.z += dLocalZ;
                    p2.x += dLocalX; p2.z += dLocalZ;
                    const updatedShape = { ...shape, points: newPoints };
                    setTempShape(updatedShape);
                }
            }
        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };
    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), e.point);
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: JSON.parse(JSON.stringify(shape.points)) }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    };
    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'top' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             const updates: Partial<IShape> = { height: ppState.dragHeight };
             if (shape && shape.type === 'flat' && ppState.dragHeight > 0.05) {
                updates.type = 'solid';
                if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR;
             }
             updateShape(ppState.hoveredShapeId, updates);
        } else if (tempShapeRef.current) {
            updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points });
        }
        setTempShape(null);
        setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined }));
        setMeasurement('');
    }, [updateShape, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);
    useEffect(() => {
        if (isDragging) {
            const onGlobalPointerUp = () => handlePointerUp();
            window.addEventListener('pointerup', onGlobalPointerUp);
            return () => window.removeEventListener('pointerup', onGlobalPointerUp);
        }
    }, [isDragging, handlePointerUp]);
    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes, updateShape, setMeasurement, activeLayerId } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [drawingHeight, setDrawingHeight] = useState(0);
    const [typedInput, setTypedInput] = useState('');

    useEffect(() => {
        setDrawPoints([]);
        setSnapInfo(null);
        setIsDragging(false);
        setDrawingHeight(0);
        setMeasurement(''); 
        setTypedInput('');
    }, [tool, setMeasurement]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        let shapeCreated = false;

        // Helper to add shape with current layer
        const createShapeObj = (base: Partial<IShape>): IShape => ({
            ...base as IShape,
            layerId: activeLayerId 
        });

        const newShapeBase: Partial<IShape> = {
             height: DEFAULT_HEIGHT,
             color: FLAT_COLOR,
             rotation: 0,
             scale: [1, 1, 1]
        };

        let newShapePoints: IPoint[] = [];

        // 1. Determine points based on tool
        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const width = Math.abs(end.x - start.x);
             const depth = Math.abs(end.z - start.z);
             if (width >= 0.01 && depth >= 0.01) {
                 const cx = (start.x + end.x) / 2;
                 const cz = (start.z + end.z) / 2;
                 const halfW = width / 2;
                 const halfD = depth / 2;
                 newShapePoints = [{ x: -halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: -halfD }];
                 newShapeBase.id = `rect-${Date.now()}`;
                 newShapeBase.type = 'flat';
                 newShapeBase.name = '地板';
                 newShapeBase.position = [cx, 0, cz];
             }
        } else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
            const start = finalPoints[0];
            const end = finalPoints[1];
            const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
            if (radius > 0.01) {
                newShapePoints = createCirclePoints(radius);
                newShapeBase.id = `circle-${Date.now()}`;
                newShapeBase.type = 'flat';
                newShapeBase.name = '圓形';
                newShapeBase.position = [start.x, 0, start.z];
            }
        } else if (tool === ToolType.DRAW_ARC && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[1];
             const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
             if (radius > 0.01) {
                 newShapePoints = createCirclePoints(radius); 
                 newShapeBase.id = `arc-${Date.now()}`;
                 newShapeBase.type = 'flat';
                 newShapeBase.name = '弧形';
                 newShapeBase.position = [start.x, 0, start.z];
             }
        } else if (tool === ToolType.MEASURE && finalPoints.length >= 3) {
            // Measure tool logic: P1, P2 (measurement points), P3 (label placement)
            // Stored directly in points array
            newShapePoints = [finalPoints[0], finalPoints[1], finalPoints[2]];
            newShapeBase.id = `dim-${Date.now()}`;
            newShapeBase.type = 'dimension';
            newShapeBase.name = '尺寸標註';
            newShapeBase.position = [0, 0, 0]; // Points are absolute world coords for dimensions
        }

        // 2. Prepare for cutting logic (Skipped for MEASURE)
        const idsToRemove = new Set<string>();
        const shapesToAddList: IShape[] = [];
        const processedEdgeIds = new Set<string>();

        let cutOccurred = false;

        // Define cutting segments based on tool or generated shape
        let cuttingSegments: {start: IPoint, end: IPoint}[] = [];

        if (tool === ToolType.DRAW_LINE && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
             if (dist >= 0.01) {
                 cuttingSegments.push({ start, end });
             }
        } else if (newShapePoints.length > 0 && newShapeBase.position && tool !== ToolType.MEASURE) {
            // Transform local points to world points for cutting segments
            const pos = newShapeBase.position as [number, number, number];
            for(let i=0; i<newShapePoints.length-1; i++){
                const p1 = newShapePoints[i];
                const p2 = newShapePoints[i+1];
                cuttingSegments.push({
                    start: { x: p1.x + pos[0], y: 0, z: p1.z + pos[2] },
                    end: { x: p2.x + pos[0], y: 0, z: p2.z + pos[2] }
                });
            }
        }

        if (cuttingSegments.length > 0) {
            // 3. Iterative Cutting Process
            // We must process segments sequentially against the current set of shapes.
            // If a shape is cut, it is replaced by its fragments for the next segment to cut.

            // Start with potential targets (flat/solid shapes, not edges)
            let workingShapes = shapes.filter(s => (s.type === 'flat' || s.type === 'solid') && s.name !== 'Edge');
            // Track which original shapes are destroyed
            const workingShapeIdsDeleted = new Set<string>();
            // Track new fragments created during this process
            let fragments: IShape[] = [];

            // Helper to add fragment to working set
            const addFragment = (parent: IShape, newPoints: IPoint[]) => {
                 const center = getBoundingCenter(newPoints);
                 const localPoints = newPoints.map(p => ({
                     x: p.x - center.x,
                     y: 0,
                     z: p.z - center.z
                 }));

                 const fragment: IShape = {
                     ...parent,
                     id: `split-${Date.now()}-${Math.random()}`,
                     points: localPoints,
                     position: [center.x, parent.position[1], center.z],
                     rotation: 0,
                     scale: [1, 1, 1]
                 };
                 return fragment;
            };

            for (const seg of cuttingSegments) {
                const nextPassShapes: IShape[] = [];
                // Combine original candidates (not yet deleted) and newly created fragments
                const currentCandidates = [...workingShapes.filter(s => !workingShapeIdsDeleted.has(s.id)), ...fragments];

                // Clear fragments list for next pass re-population, but we keep them in 'shapesToAddList' at the end
                // Actually, simpler: just iterate all current valid geometry.
                // If geometry splits, remove it from valid set, add pieces to valid set.

                let segmentCutSomething = false;

                // We need a fresh loop because we modify the list
                const shapesToProcess = [...currentCandidates];

                for (const shape of shapesToProcess) {
                    if (shape.points.length <= 2) continue;

                    const worldPoints = shape.points.map(p => {
                        const vec = transformPoint(p, shape);
                        return { x: vec.x, y: vec.y, z: vec.z };
                    });

                    const splitResult = cutPolygonBySegment(worldPoints, seg.start, seg.end);

                    if (splitResult) {
                        const [poly1, poly2] = splitResult;

                        // Mark old shape as deleted
                        if (shapes.find(s => s.id === shape.id)) {
                             idsToRemove.add(shape.id); // It's an original scene shape
                             workingShapeIdsDeleted.add(shape.id);
                        } else {
                             // It was a temporary fragment, remove it from fragments list
                             fragments = fragments.filter(f => f.id !== shape.id);
                        }

                        // Create new pieces
                        const f1 = addFragment(shape, poly1);
                        const f2 = addFragment(shape, poly2);

                        fragments.push(f1);
                        fragments.push(f2);

                        segmentCutSomething = true;
                        cutOccurred = true;
                    }
                }
            }

            if (cutOccurred) {
                // Add all surviving fragments to the add list
                shapesToAddList.push(...fragments);

                // --- 4. Re-Group Edges logic (re-used from previous Draw Line) ---
                // We also want to split edges if we are cutting line-by-line. 
                // However, for shape cutting (Rect/Circle), strictly we might just want to split the faces.
                // But to be consistent with Line tool, let's process edges too.

                const edgesToProcess: {start: IPoint, end: IPoint}[] = [];

                // Gather existing edges that intersect our cuts
                shapes.forEach(shape => {
                    if (shape.name === 'Edge' && !idsToRemove.has(shape.id)) {
                        const eps = getLineEndpoints(shape);
                        if (eps) {
                            edgesToProcess.push({ start: {x: eps[0].x, y: 0, z: eps[0].z}, end: {x: eps[1].x, y: 0, z: eps[1].z} });
                            processedEdgeIds.add(shape.id);
                        }
                    }
                });

                // Add the cutting segments themselves as new edges (so the cut is visible)
                cuttingSegments.forEach(seg => edgesToProcess.push(seg));

                const fragmented = fragmentSegments(edgesToProcess);

                // Reconstruct Edges
                 fragmented.forEach(seg => {
                    const dx = seg.end.x - seg.start.x;
                    const dz = seg.end.z - seg.start.z;
                    const len = Math.sqrt(dx*dx + dz*dz);
                    if(len < 0.001) return;

                    const angle = Math.atan2(dz, dx);
                    const cx = (seg.start.x + seg.end.x) / 2;
                    const cz = (seg.start.z + seg.end.z) / 2;

                    const halfL = len / 2;
                    const halfW = 0.01; 
                    const edgePoints = [ { x: -halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: halfW }, { x: -halfL, y: 0, z: halfW } ];

                    shapesToAddList.push(createShapeObj({ 
                        id: `edge-${Date.now()}-${Math.random()}`, 
                        type: 'flat', 
                        name: 'Edge', 
                        points: edgePoints, 
                        height: 0.005, 
                        color: '#334155', 
                        position: [cx, 0, cz], 
                        rotation: -angle, 
                        scale: [1, 1, 1] 
                    }));
                });

                // Remove old edges
                 processedEdgeIds.forEach(id => idsToRemove.add(id));

                 shapeCreated = true;
            }
        }

        // 5. Finalize
        // If we cut something, we replace the old shapes with pieces.
        // If we did NOT cut anything, and we are drawing a shape (Rect/Circle/Dimension), we add the new Shape.

        if (cutOccurred) {
             replaceShapes(Array.from(idsToRemove), shapesToAddList);
        } else if (newShapePoints.length > 0) {
             // Normal creation mode (no intersection)
             const finalNewShape: IShape = createShapeObj({
                 ...newShapeBase as IShape,
                 points: newShapePoints
             });
             addShape(finalNewShape);
             shapeCreated = true;
        } else if (tool === ToolType.DRAW_LINE && cuttingSegments.length > 0) {
             // Draw line in void (just create the edge)
              const seg = cuttingSegments[0];
              const dx = seg.end.x - seg.start.x;
              const dz = seg.end.z - seg.start.z;
              const len = Math.sqrt(dx*dx + dz*dz);
              const angle = Math.atan2(dz, dx);
              const cx = (seg.start.x + seg.end.x) / 2;
              const cz = (seg.start.z + seg.end.z) / 2;
              const halfL = len / 2;
              const edgePoints = [ { x: -halfL, y: 0, z: -0.01 }, { x: halfL, y: 0, z: -0.01 }, { x: halfL, y: 0, z: 0.01 }, { x: -halfL, y: 0, z: 0.01 } ];

              addShape(createShapeObj({ 
                id: `edge-${Date.now()}`, 
                type: 'flat', 
                name: 'Edge', 
                points: edgePoints, 
                height: 0.005, 
                color: '#334155', 
                position: [cx, 0, cz], 
                rotation: -angle, 
                scale: [1, 1, 1] 
            }));
            shapeCreated = true;
        }


        if (shapeCreated) {
            if (tool === ToolType.DRAW_LINE) {
                const lastPoint = finalPoints[finalPoints.length - 1];
                setDrawPoints([{ x: lastPoint.x, y: lastPoint.y, z: lastPoint.z }]);
                setMeasurement('');
                setTypedInput('');
            } else {
                setDrawPoints([]);
                setTool(ToolType.SELECT); 
                setMeasurement('');
                setTypedInput('');
            }
        }
    }, [tool, addShape, wallThickness, setTool, replaceShapes, updateShape, shapes, setMeasurement, activeLayerId]);

    const handleInputSubmit = useCallback(() => {
        if (!typedInput || drawPoints.length === 0) return;

        const start = drawPoints[drawPoints.length - 1];
        const startVec = new THREE.Vector3(start.x, start.y, start.z);
        const cursorVec = cursorPos.clone();

        let targetVec = new THREE.Vector3();
        const direction = cursorVec.clone().sub(startVec).normalize();

        if (tool === ToolType.DRAW_RECT) {
             const parts = typedInput.split(/[, ]+/).filter(p => p.trim() !== '').map(parseFloat);
             if (parts.length > 0 && !parts.some(isNaN)) {
                 const w = parts[0];
                 const d = parts.length > 1 ? parts[1] : w;

                 const dx = cursorVec.x - startVec.x;
                 const dz = cursorVec.z - startVec.z;
                 const signX = dx >= 0 ? 1 : -1;
                 const signZ = dz >= 0 ? 1 : -1;

                 targetVec.set(startVec.x + signX * w, startVec.y, startVec.z + signZ * d);
             } else {
                 return;
             }
        } else {
             const val = parseFloat(typedInput);
             if (isNaN(val)) return;
             if (cursorVec.distanceTo(startVec) < 0.001) {
                 direction.set(1, 0, 0);
             }
             targetVec = startVec.clone().add(direction.multiplyScalar(val));
        }

        const finalPoints = [...drawPoints, { x: targetVec.x, y: targetVec.y, z: targetVec.z }];
        finishShape(finalPoints);

    }, [typedInput, drawPoints, cursorPos, tool, finishShape]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        if (e.button !== 0) return;
        e.stopPropagation();
        setIsDragging(true);
        setTypedInput(''); 

        // FIX: Use snapped position if available
        const pt = snapInfo ? snapInfo.position.clone() : e.point.clone();

        setCursorPos(pt.clone());

        if (drawPoints.length === 0) {
            setDrawPoints([{ x: pt.x, y: pt.y, z: pt.z }]);
            if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
                 setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
            }
        } else {
            if (tool === ToolType.DRAW_LINE) {
                setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
            } else if (tool === ToolType.MEASURE) {
                 // Measure tool collects 3 points
                 setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
            }
        }
    }, [tool, drawPoints, snapInfo]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        setIsDragging(false);

        if (tool === ToolType.MEASURE) {
             if (drawPoints.length >= 3) {
                 const points = [...drawPoints];
                 // Last point is controlled by move, so we might update it one last time or use drawn points
                 // Actually logic is in finishShape, called when enough points are present.
                 // handlePointerDown adds points. 
                 // If we have 3 points now, finish.
                 finishShape(points);
             }
             return; 
        }

        if ((tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.DRAW_LINE) && drawPoints.length >= 2) {
             const points = [...drawPoints];
             points[points.length-1] = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z };
             finishShape(points);
        }
    }, [tool, drawPoints, cursorPos, finishShape]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
    }, []);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
             if ([ToolType.SELECT, ToolType.PUSH_PULL].includes(tool)) return;

             if (e.key === 'Escape') {
                 setDrawPoints([]);
                 setTool(ToolType.SELECT);
                 setMeasurement('');
                 setTypedInput('');
                 return;
             }

             if (drawPoints.length === 0) return; 

             if (e.key === 'Enter') {
                 handleInputSubmit();
                 return;
             }
             if (e.key === 'Backspace') {
                 setTypedInput(prev => prev.slice(0, -1));
                 return;
             }

             if (/^[0-9.,-]$/.test(e.key)) {
                 setTypedInput(prev => prev + e.key);
             }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, drawPoints, handleInputSubmit, setTool, setMeasurement]);

    return { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging, drawingHeight, handlePointerDown, handlePointerUp, handleClick, typedInput };
};

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Edges, Text } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.2;
const ALIGN_THRESHOLD = 0.3; // Distance to trigger alignment guide
const EPSILON = 1e-4;

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    setShapeRef: (ref: THREE.Group | null) => void; 
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

// Helper to get Axis-Aligned Bounding Box (AABB) of a shape at a specific position
const getShapeBounds = (shape: IShape, currentPos?: THREE.Vector3) => {
    const pos = currentPos || new THREE.Vector3(...shape.position);
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;

    // Create a temporary shape object with the new position to reuse transformPoint logic
    // We only need position, rotation, scale.
    const tempShape = { ...shape, position: [pos.x, pos.y, pos.z] };

    shape.points.forEach(p => {
         const wp = transformPoint(p, tempShape as IShape);
         if(wp.x < minX) minX = wp.x;
         if(wp.x > maxX) maxX = wp.x;
         if(wp.z < minZ) minZ = wp.z;
         if(wp.z > maxZ) maxZ = wp.z;
    });

    return {
        minX, maxX, minZ, maxZ,
        centerX: (minX + maxX) / 2,
        centerZ: (minZ + maxZ) / 2,
        y: pos.y
    };
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

// Robust Line Intersection (Infinite Lines)
const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null; // Parallel
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
};

// Segment Intersection (Strict, returns null if no intersection on segments)
const getSegmentIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    // Check if intersection is strictly within both segments
    if (u >= -EPSILON && u <= 1 + EPSILON && v >= -EPSILON && v <= 1 + EPSILON) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

// --- Polygon Cutting Algorithm ---
// Cuts a polygon by an infinite line defined by lineStart -> lineEnd (segment)
const cutPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    interface Intersection {
        point: IPoint;
        edgeIndex: number; // The index of the polygon edge starting point
        dist: number; // Distance from lineStart (for sorting)
    }

    const intersections: Intersection[] = [];

    // 1. Find all intersections between the cut segment and polygon edges
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];

        const hit = getSegmentIntersection(p1, p2, lineStart, lineEnd);

        if (hit) {
            // Avoid duplicate points
            const isDuplicate = intersections.some(
                intr => Math.abs(intr.point.x - hit.x) < 0.001 && Math.abs(intr.point.z - hit.z) < 0.001
            );
            if (!isDuplicate) {
                const dist = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    // We need exactly 2 intersection points for a simple split
    if (intersections.length < 2) return null;

    // Sort by distance along the cut line
    intersections.sort((a, b) => a.dist - b.dist);

    // Take the first two (entry and exit)
    const [startHit, endHit] = intersections;

    const getVerticesBetween = (idx1: number, idx2: number) => {
        const verts: IPoint[] = [];
        let i = (idx1 + 1) % polyPoints.length;
        while (i !== (idx2 + 1) % polyPoints.length) {
            verts.push(polyPoints[i]);
            i = (i + 1) % polyPoints.length;
        }
        return verts;
    };

    const polyA_verts = getVerticesBetween(startHit.edgeIndex, endHit.edgeIndex);
    const polyA = [startHit.point, ...polyA_verts, endHit.point];

    const polyB_verts = getVerticesBetween(endHit.edgeIndex, startHit.edgeIndex);
    const polyB = [endHit.point, ...polyB_verts, startHit.point];

    return [polyA, polyB];
};


const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;

    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });

    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];

    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 

    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;

    const p1 = new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz);
    const p2 = new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz);

    return [p1, p2];
};

// --- Face Detection & Planar Graph Algorithms ---
const fragmentSegments = (segments: { start: IPoint; end: IPoint }[]): { start: IPoint; end: IPoint }[] => {
    let currentSegments = [...segments];
    let hasIntersections = true;
    let iterations = 0;

    while (hasIntersections && iterations < 50) {
        hasIntersections = false;
        iterations++;
        const newSegments: { start: IPoint; end: IPoint }[] = [];
        const processed = new Set<number>();

        for (let i = 0; i < currentSegments.length; i++) {
            if (processed.has(i)) continue;
            let s1 = currentSegments[i];
            let broken = false;

            for (let j = i + 1; j < currentSegments.length; j++) {
                if (processed.has(j)) continue;
                let s2 = currentSegments[j];

                const intersection = getSegmentIntersection(s1.start, s1.end, s2.start, s2.end);

                const isEndpoint = (p: IPoint, s: {start: IPoint, end: IPoint}) => 
                    (Math.abs(p.x - s.start.x) < 0.001 && Math.abs(p.z - s.start.z) < 0.001) ||
                    (Math.abs(p.x - s.end.x) < 0.001 && Math.abs(p.z - s.end.z) < 0.001);

                if (intersection && !isEndpoint(intersection, s1) && !isEndpoint(intersection, s2)) {
                    // Split s1
                    newSegments.push({ start: s1.start, end: intersection });
                    newSegments.push({ start: intersection, end: s1.end });
                    // Split s2
                    newSegments.push({ start: s2.start, end: intersection });
                    newSegments.push({ start: intersection, end: s2.end });

                    processed.add(i);
                    processed.add(j);
                    broken = true;
                    hasIntersections = true;
                    break; 
                }
            }
            if (!broken) {
                newSegments.push(s1);
            }
        }
        if (hasIntersections) {
            currentSegments = newSegments;
        }
    }
    return currentSegments;
};

const findClosedCycles = (segments: { start: IPoint; end: IPoint }[]): IPoint[][] => {
    const nodes: Record<string, { x: number, z: number, neighbors: string[] }> = {};
    const key = (p: IPoint) => `${p.x.toFixed(3)},${p.z.toFixed(3)}`;
    const addNode = (p: IPoint) => {
        const k = key(p);
        if (!nodes[k]) nodes[k] = { x: p.x, z: p.z, neighbors: [] };
        return k;
    };

    // Build Graph
    segments.forEach(s => {
        if (Math.abs(s.start.x - s.end.x) < 0.001 && Math.abs(s.start.z - s.end.z) < 0.001) return;
        const k1 = addNode(s.start);
        const k2 = addNode(s.end);
        if (!nodes[k1].neighbors.includes(k2)) nodes[k1].neighbors.push(k2);
        if (!nodes[k2].neighbors.includes(k1)) nodes[k2].neighbors.push(k1);
    });

    const cycles: IPoint[][] = [];
    const visitedEdges = new Set<string>();

    Object.keys(nodes).forEach(uKey => {
        const uNode = nodes[uKey];
        // Sort neighbors by angle
        uNode.neighbors.sort((aKey, bKey) => {
            const aNode = nodes[aKey];
            const bNode = nodes[bKey];
            const angA = Math.atan2(aNode.z - uNode.z, aNode.x - uNode.x);
            const angB = Math.atan2(bNode.z - uNode.z, bNode.x - uNode.x);
            return angA - angB;
        });

        uNode.neighbors.forEach(vKey => {
            const edgeKey = `${uKey}->${vKey}`;
            if (visitedEdges.has(edgeKey)) return;

            const path = [uKey];
            const pathSet = new Set([uKey]);
            let curr = vKey;
            let prev = uKey;
            let isCycle = false;

            // Turn Left Rule (CCW)
            const MAX_PATH = 50; 
            for(let i=0; i<MAX_PATH; i++) {
                visitedEdges.add(`${prev}->${curr}`);
                path.push(curr);

                if (curr === uKey) {
                    isCycle = true;
                    break;
                }

                if (pathSet.has(curr)) break; // Loop
                pathSet.add(curr);

                const currNode = nodes[curr];
                const neighbors = currNode.neighbors;
                const prevIdx = neighbors.indexOf(prev);
                const nextIdx = (prevIdx - 1 + neighbors.length) % neighbors.length;
                const nextKey = neighbors[nextIdx];

                if (!nextKey || nextKey === prev) break;

                prev = curr;
                curr = nextKey;
            }

            if (isCycle && path.length > 3) {
                const points = path.slice(0, -1).map(k => ({ x: nodes[k].x, y: 0, z: nodes[k].z }));

                // Calculate Area (Shoelace)
                let area = 0;
                for(let i=0; i<points.length; i++) {
                    const p1 = points[i];
                    const p2 = points[(i+1)%points.length];
                    area += (p2.x - p1.x) * (p2.z + p1.z);
                }

                if (Math.abs(area) > 0.01) {
                    cycles.push(points);
                }
            }
        });
    });

    // Deduplicate
    const uniqueCycles: IPoint[][] = [];
    const cycleFingerprints = new Set<string>();

    cycles.forEach(cycle => {
        let cx = 0, cz = 0;
        cycle.forEach(p => { cx += p.x; cz += p.z });
        cx /= cycle.length;
        cz /= cycle.length;
        const fingerprint = `${cx.toFixed(3)},${cz.toFixed(3)}_${cycle.length}`;
        if (!cycleFingerprints.has(fingerprint)) {
            cycleFingerprints.add(fingerprint);
            uniqueCycles.push(cycle);
        }
    });

    return uniqueCycles;
};


const getBoundingCenter = (points: IPoint[]) => {
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x;
        if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z;
    });
    return { x: (minX + maxX) / 2, z: (minZ + maxZ) / 2 };
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {

    let bestSnap: SnapResult;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    if (intersectedObject && shapeData) {
        bestSnap = { 
            position: intersectedObject.point, 
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id 
        };
    } else {
        bestSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            type: 'grid',
            distance: Infinity
        };
    }

    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ptVec.distanceTo(cursorPos);
        if (dist < threshold * 1.5) {
            return { position: ptVec, type: 'endpoint', distance: dist };
        }
    }

    for (const shape of shapes) {
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 for(const ep of endpoints) {
                     if (Math.abs(ep.y - cursorPos.y) < 0.2) {
                         const dist = ep.distanceTo(cursorPos);
                         if (dist < threshold) {
                             if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                                 bestSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id };
                             }
                         }
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);

            if (dist < threshold) {
                 if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                    bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
                 }
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold) {
                     if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                        bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                     }
                }
            }
        }
    }

    if (bestSnap.type === 'vertex' || bestSnap.type === 'endpoint') return bestSnap;

    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);

                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }

                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }

    if (bestEdgeSnap) return bestEdgeSnap;

    return bestSnap;
};

