const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid') return null;

    let color = 'orange';
    if (type === 'midpoint') color = 'cyan';
    else if (type === 'vertex' || type === 'endpoint') color = '#f59e0b'; 
    else if (type === 'face') color = '#3b82f6'; 

    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments>
                        <edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} />
                        <lineBasicMaterial color={color} depthTest={false} />
                    </lineSegments>
                 </mesh>
            ) : (
                <mesh>
                    <sphereGeometry args={[type === 'vertex' || type === 'endpoint' ? 0.15 : 0.05]} />
                    <meshBasicMaterial color={color} depthTest={false} />
                    {(type === 'vertex' || type === 'endpoint') && (
                        <mesh scale={1.5}>
                             <sphereGeometry args={[0.15]} />
                             <meshBasicMaterial color={color} transparent opacity={0.3} depthTest={false} />
                        </mesh>
                    )}
                </mesh>
            )}

            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid') return null;

    let displayType = '';
    let isWarning = false;

    switch(type) {
        case 'vertex': 
            displayType = '頂點'; 
            isWarning = true;
            break;
        case 'midpoint': displayType = '中點'; break;
        case 'edge': displayType = '邊緣'; break;
        case 'face': displayType = '表面'; break;
        case 'endpoint': 
            displayType = '端點'; 
            isWarning = true;
            break;
        case 'align': displayType = '對齊'; break;
        default: displayType = '';
    }

    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;

    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`text-xs px-2 py-1.5 rounded-lg backdrop-blur-md border shadow-xl whitespace-nowrap flex items-center gap-1.5 transition-all duration-200 transform
                ${isWarning 
                    ? 'bg-amber-500/95 text-white border-amber-300 scale-110 font-bold' 
                    : 'bg-slate-900/80 text-white border-slate-600'
                }`}
            >
                {type && !isWarning && <span className={`w-2 h-2 rounded-full ${type === 'face' ? 'bg-blue-500' : 'bg-green-500'}`} />}

                {isWarning && (
                     <span className="flex h-3 w-3 relative justify-center items-center">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-2 w-2 bg-white"></span>
                     </span>
                )}

                {displayText}
            </div>
        </Html>
    );
};

