const Scene: React.FC = () => {
    const { 
        shapes, 
        selectedIds, 
        selectShape, 
        updateShape, 
        tool, 
        transformMode,
        layers,
        setMeasurement,
        addShape
    } = useApp();

    const { camera, raycaster, gl } = useThree();
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        // Basic plane intersection for cursor
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const pt = new THREE.Vector3();
        e.ray.intersectPlane(plane, pt);

        // Snap logic
        const snap = getGeometrySnap(pt, shapes, drawPoints, SNAP_THRESHOLD);
        setCursorPos(snap.position);
        setSnapInfo(snap);

        setMeasurement(`X: ${snap.position.x.toFixed(2)}, Z: ${snap.position.z.toFixed(2)}`);
    };

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        e.stopPropagation();
        if (tool === ToolType.SELECT) return; // Select is handled by shape click

        if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT].includes(tool)) {
            const pt = { x: snapInfo?.position.x || cursorPos.x, y: 0, z: snapInfo?.position.z || cursorPos.z };
            if (drawPoints.length === 0) {
                setDrawPoints([pt]);
            } else {
                // Finish drawing
                const start = drawPoints[0];
                const end = pt;

                let points: IPoint[] = [];
                if (tool === ToolType.DRAW_RECT) {
                    points = [
                        { x: start.x, y: 0, z: start.z },
                        { x: end.x, y: 0, z: start.z },
                        { x: end.x, y: 0, z: end.z },
                        { x: start.x, y: 0, z: end.z },
                        { x: start.x, y: 0, z: start.z },
                    ];
                } else {
                    points = [start, end];
                }

                addShape({
                    id: `shape-${Date.now()}`,
                    layerId: layers[0].id,
                    type: 'solid',
                    name: tool === ToolType.DRAW_RECT ? 'Room' : 'Line',
                    points,
                    height: tool === ToolType.DRAW_RECT ? 3 : DEFAULT_HEIGHT,
                    color: DEFAULT_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                });
                setDrawPoints([]);
            }
        }
    };

    const visibleShapes = useMemo(() => {
        return shapes.filter(s => {
            const l = layers.find(layer => layer.id === s.layerId);
            return l ? l.visible : true;
        });
    }, [shapes, layers]);

    return (
        <>
            <gridHelper args={[60, 60, 0xddd, 0xf0f0f0]} position={[0, 0.01, 0]} />
            <axesHelper args={[5]} />

            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />

            {/* Interaction Plane */}
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, -0.01, 0]} 
                onPointerMove={handlePointerMove}
                onPointerDown={handlePointerDown}
            >
                <planeGeometry args={[100, 100]} />
                <meshBasicMaterial visible={false} />
            </mesh>

            {visibleShapes.map(shape => (
                <ShapeRenderer
                    key={shape.id}
                    shape={shape}
                    isSelected={selectedIds.includes(shape.id)}
                    onSelect={(e) => {
                        if (tool === ToolType.SELECT) {
                            e.stopPropagation();
                            selectShape(shape.id, e.ctrlKey);
                        }
                    }}
                />
            ))}

            {/* Transform Controls */}
            {tool === ToolType.SELECT && selectedIds.length === 1 && (
                <TransformControls 
                    object={undefined} 
                    mode={transformMode}
                    onMouseUp={() => { 
                         // Handle update logic if needed or use onChange
                    }}
                >
                    {/* Invisible anchor since we control shapes via React state, simpler to just use Gizmo or implement custom Drag */}
                </TransformControls>
            )}

            {/* Drawing Preview */}
            {drawPoints.length > 0 && (
                <Line 
                    points={[
                        new THREE.Vector3(drawPoints[0].x, 0.1, drawPoints[0].z), 
                        new THREE.Vector3(cursorPos.x, 0.1, cursorPos.z)
                    ]} 
                    color="red" 
                    lineWidth={2} 
                />
            )}

            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {snapInfo && <CursorTooltip position={snapInfo.position} text="" type={snapInfo.type} />}
        </>
    );
};

const Viewport: React.FC = () => {
    return (
        <div className="w-full h-full bg-slate-50 relative">
            <Canvas shadows camera={{ position: [5, 8, 10], fov: 45 }}>
                <OrbitControls makeDefault />
                <Scene />
                <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                    <GizmoViewport axisColors={['#9d4b4b', '#2f7f4f', '#3b5b9d']} labelColor="white" />
                </GizmoHelper>
            </Canvas>
            <AIAssistant />
        </div>
    );
};

export default Viewport;
